<script lang="ts">
import {onMount} from 'svelte';import {api,mutation} from '$lib/client/api';import {notify} from '$lib/client/toast';import Input from '../ui/Input.svelte';import Button from '../ui/Button.svelte';
type Definition={id:string;name:string;code:string;workflowType:string;active:boolean};
let definitions=$state<Definition[]>([]),form=$state({name:'',code:'',workflowType:'leave'}),message=$state(''),error=$state(''),busy=$state(false),loading=$state(true);
async function load(){loading=true;try{definitions=(await api<{definitions:Definition[]}>('/api/app/workflows')).definitions;}catch(e){error=(e as Error).message;}finally{loading=false;}}
onMount(()=>{void load();});
async function submit(e:SubmitEvent){e.preventDefault();if(busy)return;busy=true;message='Saving workflow…';error='';try{await mutation('/api/app/workflows','POST',{...form,steps:[{name:'Reporting manager',actorType:'reporting_manager'}]});message='Workflow activated.';notify(message,'success');form={name:'',code:'',workflowType:'leave'};await load();}catch(e){error=(e as Error).message;notify(error,'error');}finally{busy=false;}}
</script>
<div class="space-y-6">{#if error}<p role="alert" class="text-sm text-danger">{error}</p>{/if}<div class="grid gap-3">{#if loading}<p class="text-sm text-muted">Loading workflows…</p>{:else if !definitions.length}<p class="text-sm text-muted">No workflows configured yet.</p>{:else}{#each definitions as definition}<div class="flex items-center justify-between rounded-xl border p-4 bg-surface shadow-sm"><div><p class="font-medium text-primary">{definition.name}</p><p class="text-sm text-muted">{definition.workflowType} · {definition.code}</p></div><span class="text-sm text-success font-medium">{definition.active?'Active':'Inactive'}</span></div>{/each}{/if}</div>
<form onsubmit={submit} class="grid gap-4 border-t pt-5 md:grid-cols-3"><label class="grid gap-1 text-sm">Name<Input required bind:value={form.name}/></label><label class="grid gap-1 text-sm">Code<Input required bind:value={form.code}/></label><label class="grid gap-1 text-sm">Workflow type<select class="h-10 rounded-lg border bg-surface px-3" bind:value={form.workflowType}><option value="leave">Leave</option><option value="attendance_regularization">Attendance regularization</option></select></label><div class="md:col-span-3"><Button type="submit" disabled={busy}>{busy?'Activating…':'Activate workflow'}</Button><p aria-live="polite" class="mt-2 text-sm text-muted">{message}</p></div></form></div>

